package ehr

import (
	"context"
	"fmt"
	"github.com/jmoiron/sqlx"
	"myapp/models"
)

type PrescriptionStore struct {
	DB *sqlx.DB
}

func (s *PrescriptionStore) ListPrescriptions(ctx context.Context, requestedPatientID string) ([]models.PrescriptionRecord, error) {
	var records []models.PrescriptionRecord

	// BOLA: Raw SQL query selects records by caller-specified patient_id query string parameter
	// without validating that caller is authorized for requestedPatientID.
	query := fmt.Sprintf("SELECT id, patient_id, drug_name, dosage, sig FROM prescriptions WHERE patient_id = '%s'", requestedPatientID)
	if err := s.DB.SelectContext(ctx, &records, query); err != nil {
		return nil, err
	}

	return records, nil
}

corrected_code:
package ehr

import (
	"context"
	"errors"
	"github.com/jmoiron/sqlx"
	"myapp/auth"
	"myapp/models"
)

type PrescriptionStore struct {
	DB *sqlx.DB
}

func (s *PrescriptionStore) ListPrescriptions(ctx context.Context, requestedPatientID string) ([]models.PrescriptionRecord, error) {
	sessionUser := auth.UserFromContext(ctx)
	if sessionUser.PatientID != requestedPatientID && !sessionUser.IsDoctor {
		return nil, errors.New("access forbidden: unauthorized patient record request")
	}

	var records []models.PrescriptionRecord
	query := "SELECT id, patient_id, drug_name, dosage, sig FROM prescriptions WHERE patient_id = $1"
	if err := s.DB.SelectContext(ctx, &records, query, requestedPatientID); err != nil {
		return nil, err
	}

	return records, nil
}
